source:
[_meta]
sections_order = ["abbreviations", "caps", "terms", "unknown"]
delay = 0.5
[_meta.section_delays]
caps = 0.2
terms = 0.3
abbreviations = 0.4
[[caps]]
"firstx" = { output = "First", is_word = true, is_case_sensitive = true, auto_expand = true, final_result = true }
[[terms]]
"secondx" = { output = "Second", is_word = false, auto_expand = true, is_case_sensitive = true, is_case_sensitive_strict = true, priority = 44 }
[[caps]]
"thirdx" = { output = "Third", is_word = true, is_case_sensitive = true, auto_expand = false }
[[abbreviations]]
"fourthx" = { output = "Fourth", is_word = true, is_case_sensitive = true, auto_expand = true }
[[unknown]]
"unknownx" = { output = "Unknown", is_word = true, is_case_sensitive = true, auto_expand = true }
[[caps]]
"sixthx" = { output = "Sixth", is_word = false, is_case_sensitive = true, auto_expand = true }

